version.transform:
(
  $convertUnitWeight := function($value,$unitWeight) {
      $value * $unitWeight
  };

  $.(
    $unitWeight := unitWeight;
    inventory~>| $ | (
      $quantityValue := quantity.value;

      {
        "grossWeight": {
          "value": $convertUnitWeight($quantityValue,$unitWeight),
          "unitId": grossWeight.unitId
        },
        "netWeight": {
          "value": $convertUnitWeight($quantityValue,$unitWeight) - tareWeight.value,
          "unitId": netWeight.unitId
        }
      }
    )|
  );
)
